#include <array>      // std::array: fixed-size container used for the 9x9 grid
#include <fstream>    // std::ifstream: reads the puzzle files
#include <iostream>   // std::cout / std::ostream: console output
#include <string>     // std::string: file names
#include <vector>     // std::vector: holds the list of solutions found

/*
 * AUTHORSHIP: [GENAI-CLAUDE]
 * Class Sudoku: one object represents one 9x9 puzzle grid. It knows how to
 * load itself from a file, print itself, check whether a digit may be placed
 * in a cell, and recursively search for every solution. All of the solving
 * logic lives in member functions of this object (no free functions).
 */
class Sudoku {
public:
    static const int N = 9;   // grid size: 9 rows and 9 columns

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * Constructor: remembers the file name, zeroes the grid (0 means blank),
     * then tries to load the puzzle from the file and records success/failure.
     */
    explicit Sudoku(const std::string& filename) : name_(filename), loaded_(false) {
        for (auto& row : grid_) row.fill(0);   // set every cell in every row to 0 (blank)
        loaded_ = load(filename);              // read the file; store whether it worked
    }

    bool loaded() const { return loaded_; }          // true if the file held a valid 81-cell puzzle
    const std::string& name() const { return name_; } // returns the puzzle's file name

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * solveAll: runs the search and returns how many solutions exist.
     * It works on a COPY of the puzzle so the original givens stay intact
     * for printing, and stores every complete grid in solutions_.
     */
    int solveAll() {
        solutions_.clear();                  // discard results from any earlier call
        Sudoku work = *this;                 // make a working copy of the puzzle
        work.search(solutions_);             // run the search; it appends each solution found
        return static_cast<int>(solutions_.size());  // number of solutions found
    }

    // Returns the list of solutions found by solveAll().
    const std::vector<Sudoku>& solutions() const { return solutions_; }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * print: writes the grid to the given stream with separators between 3x3
     * blocks. Blank cells are shown as '_' and filled cells as their digit.
     */
    void print(std::ostream& os) const {
        for (int r = 0; r < N; ++r) {                                  // go through each row
            if (r % 3 == 0 && r != 0) os << "------+-------+------\n"; // horizontal line between block rows
            for (int c = 0; c < N; ++c) {                              // go through each column
                if (c % 3 == 0 && c != 0) os << "| ";                  // vertical bar between block columns
                os << (grid_[r][c] ? char('0' + grid_[r][c]) : '_');   // digit if filled, '_' if blank
                os << (c < N - 1 ? " " : "");                          // space between cells (none after last)
            }
            os << '\n';                                                // end of the row
        }
    }

private:
    std::string name_;                          // file name this puzzle came from
    bool loaded_;                               // did the file load correctly?
    std::array<std::array<int, N>, N> grid_;    // the 9x9 grid; 0 = blank, 1-9 = digit
    std::vector<Sudoku> solutions_;             // solutions found (used on the top-level object)

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * load: reads the file one character at a time. Digits 1-9 are givens;
     * '_' (also '0' or '.') is a blank. Whitespace and anything else is
     * skipped. Succeeds only if exactly 81 cells were read.
     */
    bool load(const std::string& filename) {
        std::ifstream in(filename);          // open the puzzle file
        if (!in) return false;               // file could not be opened
        int count = 0;                       // how many cells have been read so far
        char ch;                             // the character currently being examined
        while (in.get(ch) && count < N * N) {                     // read until EOF or 81 cells
            if (ch >= '1' && ch <= '9')                            // a given digit
                grid_[count / N][count % N] = ch - '0', ++count;   // store it at (row, col), advance
            else if (ch == '_' || ch == '0' || ch == '.') ++count; // a blank: leave 0, advance
        }
        return count == N * N;               // valid only if we got all 81 cells
    }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * isCandidate: returns true if digit d can legally go in cell (r, c),
     * meaning d does not already appear in that row, column, or 3x3 block.
     */
    bool isCandidate(int r, int c, int d) const {
        for (int i = 0; i < N; ++i) {            // scan along the row and the column together
            if (grid_[r][i] == d) return false;  // d already in this row
            if (grid_[i][c] == d) return false;  // d already in this column
        }
        int br = (r / 3) * 3;                    // top row of the 3x3 block containing (r, c)
        int bc = (c / 3) * 3;                    // left column of that block
        for (int i = 0; i < 3; ++i)              // scan the 3 rows of the block
            for (int j = 0; j < 3; ++j)          // scan the 3 columns of the block
                if (grid_[br + i][bc + j] == d) return false;  // d already in this block
        return true;                             // no conflicts: d is a valid candidate
    }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * findEmpty: finds the first blank cell in row-major order. Returns its
     * position through r and c; returns false if there are no blanks left.
     */
    bool findEmpty(int& r, int& c) const {
        for (r = 0; r < N; ++r)                  // go through rows top to bottom
            for (c = 0; c < N; ++c)              // go through columns left to right
                if (grid_[r][c] == 0) return true;  // found a blank; r and c hold its position
        return false;                            // grid is full
    }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * givensValid: checks that the digits already in the puzzle do not break
     * any rule (otherwise no solution can exist). Each given is temporarily
     * removed and tested as a candidate in its own cell, then put back.
     */
    bool givensValid() {
        for (int r = 0; r < N; ++r)              // every row
            for (int c = 0; c < N; ++c) {        // every column
                int d = grid_[r][c];             // digit in this cell
                if (!d) continue;                // skip blanks
                grid_[r][c] = 0;                 // temporarily remove the digit
                bool ok = isCandidate(r, c, d);  // would it be legal here with itself removed?
                grid_[r][c] = d;                 // restore the digit
                if (!ok) return false;           // a given conflicts with another given
            }
        return true;                             // all givens are consistent
    }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * search: entry point for the search. Rejects puzzles whose givens already
     * conflict, otherwise starts the recursion.
     */
    void search(std::vector<Sudoku>& found) {
        if (!givensValid()) return;   // contradictory puzzle: no solutions
        recurse(found);               // begin depth-first search
    }

    /*
     * AUTHORSHIP: [GENAI-CLAUDE]
     * recurse: the recursive depth-first search with backtracking.
     *   Base case: no blank cell remains (k == 81), so the grid is a complete
     *              valid solution; save a copy of it.
     *   Recursive case: pick the first blank cell, try each legal digit in it,
     *              recurse with one more cell filled, then undo the digit
     *              (backtrack) and try the next. It does not stop at the first
     *              solution, so every solution is found. If a cell has no
     *              candidates, the loop places nothing and the call simply
     *              returns, which reports "no solution" on this path.
     */
    void recurse(std::vector<Sudoku>& found) {
        int r, c;                                 // position of the chosen blank cell
        if (!findEmpty(r, c)) {                   // base case: no blanks left
            Sudoku copy = *this;                  // copy the completed grid
            copy.solutions_.clear();              // the copy does not need its own solution list
            found.push_back(copy);                // record this solution
            return;                               // go back up to keep looking for more
        }
        for (int d = 1; d <= 9; ++d) {            // try every digit 1-9 in this cell
            if (isCandidate(r, c, d)) {           // only if it breaks no row/column/block rule
                grid_[r][c] = d;                  // place the digit
                recurse(found);                   // recursive call with k+1 cells filled
                grid_[r][c] = 0;                  // backtrack: remove the digit and try the next
            }
        }
    }
};

/*
 * AUTHORSHIP: [GENAI-CLAUDE]
 * main: builds the list of puzzle files (from the command line, or
 * puzzle1.txt..puzzle5.txt by default). For each file it creates a Sudoku
 * object, prints the file name and the puzzle, solves it, then prints each
 * solution or "No solution found".
 */
int main(int argc, char* argv[]) {
    std::vector<std::string> files;                          // names of the puzzle files to solve
    for (int i = 1; i < argc; ++i) files.push_back(argv[i]); // use any file names given on the command line
    if (files.empty())                                       // none given: use the defaults
        for (int i = 1; i <= 5; ++i) files.push_back("puzzle" + std::to_string(i) + ".txt");

    for (const auto& f : files) {                            // process each puzzle file in turn
        std::cout << "==============================\n";     // separator line between puzzles
        std::cout << "File: " << f << "\n\n";                // print the puzzle file name

        Sudoku puzzle(f);                                    // create the puzzle object (loads the file)
        if (!puzzle.loaded()) {                              // file missing or not a valid 9x9 puzzle
            std::cout << "Could not read a valid 9x9 puzzle from this file.\n\n";
            continue;                                        // skip to the next file
        }

        std::cout << "Puzzle:\n";                            // label for the original puzzle
        puzzle.print(std::cout);                             // print the puzzle as read from the file
        std::cout << '\n';                                   // blank line

        int n = puzzle.solveAll();                           // search; n = number of solutions found
        if (n == 0) {                                        // nothing found
            std::cout << "No solution found\n\n";            // required message for unsolvable puzzles
        } else {
            for (int i = 0; i < n; ++i) {                    // print every solution
                std::cout << "Solution";                     // heading for this solution
                if (n > 1) std::cout << " " << (i + 1) << " of " << n;  // number them if several
                std::cout << ":\n";                          // end of heading
                puzzle.solutions()[i].print(std::cout);      // print the solved grid
                std::cout << '\n';                           // blank line
            }
        }
    }
    return 0;                                                // normal exit
}